<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

use Override;
use DateInterval;
use DateTimeImmutable;

class AuthenticationContext implements \JsonSerializable
{
    public const string LEVEL_ANONYMOUS = 'ANONYMOUS';
    public const string LEVEL_PASSWORD = 'PASSWORD';
    public const string LEVEL_PASSWORD_HTTPS = 'PASSWORD_HTTPS';
    public const string LEVEL_MFA = 'MFA';
    public const string LEVEL_REMEMBERED = 'REMEMBERED';

    private readonly DateTimeImmutable $authenticatedAt;
    private readonly DateInterval $authenticationAge;

    public function __construct(
        private readonly string $level = self::LEVEL_ANONYMOUS,
        private readonly bool $mfa = false,
        private readonly bool $rememberMe = false,
        private readonly bool $impersonated = false,
        private readonly bool $secureTransport = false,
        ?DateTimeImmutable $authenticatedAt = null,
        ?DateInterval $authenticationAge = null,
        private readonly ?string $authenticationMethod = null,
        private readonly string $sessionId = '',
        private readonly ?Identity $authenticatedActor = null,
        private readonly ?Identity $effectiveActor = null,
    ) {
        $this->authenticatedAt = $authenticatedAt ?? new DateTimeImmutable();
        $this->authenticationAge = $authenticationAge ?? new DateInterval('PT0S');
    }

    public static function anonymous(): self
    {
        return new self();
    }

    public function getLevel(): string { return $this->level; }
    public function isMfa(): bool { return $this->mfa; }
    public function isRememberMe(): bool { return $this->rememberMe; }
    public function isImpersonated(): bool { return $this->impersonated; }
    public function isSecureTransport(): bool { return $this->secureTransport; }
    public function getAuthenticatedAt(): DateTimeImmutable { return $this->authenticatedAt; }
    public function getAuthenticationAge(): DateInterval { return $this->authenticationAge; }
    public function getAuthenticationMethod(): ?string { return $this->authenticationMethod; }
    public function getSessionId(): string { return $this->sessionId; }
    public function getAuthenticatedActor(): ?Identity { return $this->authenticatedActor; }
    public function getEffectiveActor(): ?Identity { return $this->effectiveActor; }

    public function jsonSerialize(): array
    {
        $now = new DateTimeImmutable();
        $ageMillis = max(0, ($now->getTimestamp() - $this->authenticatedAt->getTimestamp()) * 1000);
        return [
            'level' => $this->level,
            'mfa' => $this->mfa,
            'rememberMe' => $this->rememberMe,
            'impersonated' => $this->impersonated,
            'secureTransport' => $this->secureTransport,
            'authenticatedAt' => $this->authenticatedAt->format(DATE_ATOM),
            'authenticationAge' => $ageMillis,
            'authenticationMethod' => $this->authenticationMethod ?? '',
            'sessionId' => $this->sessionId,
        ];
    }
}
